CREATE TABLE public.commerce_documents(id uuid PRIMARY KEY,business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE RESTRICT,branch_id uuid NOT NULL,period_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('sale','purchase','sale_return','purchase_return','purchase_order','goods_receipt')),source_id uuid,party_id uuid,status text NOT NULL CHECK(status IN ('draft','confirmed')),document_date date NOT NULL,reference text NOT NULL CHECK(length(btrim(reference)) BETWEEN 1 AND 200),lines jsonb NOT NULL CHECK(jsonb_typeof(lines)='array'),subtotal numeric(18,2) NOT NULL DEFAULT 0,tax numeric(18,2) NOT NULL DEFAULT 0,total numeric(18,2) NOT NULL DEFAULT 0 CHECK(total>=0 AND total::text NOT IN ('NaN','Infinity','-Infinity')),actor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,request jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(business_id,id),FOREIGN KEY(business_id,branch_id) REFERENCES public.branches(business_id,id) ON DELETE RESTRICT,FOREIGN KEY(period_id) REFERENCES public.financial_periods(id) ON DELETE RESTRICT,FOREIGN KEY(business_id,party_id) REFERENCES public.parties(business_id,id) ON DELETE RESTRICT,FOREIGN KEY(business_id,source_id) REFERENCES public.commerce_documents(business_id,id) ON DELETE RESTRICT);
REVOKE ALL ON public.commerce_documents FROM anon,authenticated;GRANT SELECT ON public.commerce_documents TO authenticated;GRANT ALL ON public.commerce_documents TO service_role;
ALTER TABLE public.commerce_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY commerce_documents_read ON public.commerce_documents FOR SELECT TO authenticated USING(public.can_access_branch(business_id,branch_id));
CREATE INDEX commerce_documents_lookup ON public.commerce_documents(business_id,branch_id,document_date);
CREATE TABLE public.commerce_stock_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE RESTRICT,branch_id uuid NOT NULL,variant_id uuid NOT NULL,document_id uuid NOT NULL,quantity numeric(18,3) NOT NULL CHECK(quantity<>0),kind text NOT NULL,reference text NOT NULL,reason text NOT NULL,actor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(business_id,branch_id) REFERENCES public.branches(business_id,id) ON DELETE RESTRICT,FOREIGN KEY(business_id,variant_id) REFERENCES public.product_variants(business_id,id) ON DELETE RESTRICT,FOREIGN KEY(business_id,document_id) REFERENCES public.commerce_documents(business_id,id) ON DELETE RESTRICT);
REVOKE ALL ON public.commerce_stock_movements FROM anon,authenticated;GRANT SELECT ON public.commerce_stock_movements TO authenticated;GRANT ALL ON public.commerce_stock_movements TO service_role;
ALTER TABLE public.commerce_stock_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY commerce_stock_read ON public.commerce_stock_movements FOR SELECT TO authenticated USING(public.can_access_branch(business_id,branch_id));
CREATE INDEX commerce_stock_lookup ON public.commerce_stock_movements(business_id,branch_id,variant_id);
CREATE TABLE public.commerce_journal_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE RESTRICT,branch_id uuid NOT NULL,period_id uuid NOT NULL,source_id uuid NOT NULL,source_type text NOT NULL,entry_date date NOT NULL,account_code text NOT NULL CHECK(account_code IN ('cash','bank','wallet','receivable','payable','sales','purchases','vat_output','vat_input','counter_clearing')),debit numeric(18,2) NOT NULL DEFAULT 0 CHECK(debit>=0),credit numeric(18,2) NOT NULL DEFAULT 0 CHECK(credit>=0),actor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)),FOREIGN KEY(business_id,branch_id) REFERENCES public.branches(business_id,id) ON DELETE RESTRICT,FOREIGN KEY(period_id) REFERENCES public.financial_periods(id) ON DELETE RESTRICT);
REVOKE ALL ON public.commerce_journal_entries FROM anon,authenticated;GRANT SELECT ON public.commerce_journal_entries TO authenticated;GRANT ALL ON public.commerce_journal_entries TO service_role;
ALTER TABLE public.commerce_journal_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY commerce_journal_read ON public.commerce_journal_entries FOR SELECT TO authenticated USING(public.can_access_branch(business_id,branch_id));
CREATE INDEX commerce_journal_source ON public.commerce_journal_entries(business_id,source_id);
CREATE FUNCTION public.check_commerce_journal_balance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.commerce_journal_entries WHERE business_id=NEW.business_id AND source_id=NEW.source_id GROUP BY source_id HAVING sum(debit)<>sum(credit)) THEN RAISE EXCEPTION 'Financial entry does not balance';END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.check_commerce_journal_balance() FROM PUBLIC,anon,authenticated;
CREATE CONSTRAINT TRIGGER commerce_journal_balance AFTER INSERT ON public.commerce_journal_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_commerce_journal_balance();
CREATE TABLE public.cash_counter_events(id uuid PRIMARY KEY,business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE RESTRICT,branch_id uuid NOT NULL,period_id uuid NOT NULL,session_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('open','in','out','close')),amount numeric(18,2) NOT NULL CHECK(amount>=0 AND amount::text NOT IN ('NaN','Infinity','-Infinity')),expected numeric(18,2),difference numeric(18,2),reference text NOT NULL,actor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,event_date date NOT NULL,request jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(business_id,id),FOREIGN KEY(business_id,branch_id) REFERENCES public.branches(business_id,id) ON DELETE RESTRICT,FOREIGN KEY(period_id) REFERENCES public.financial_periods(id) ON DELETE RESTRICT);
REVOKE ALL ON public.cash_counter_events FROM anon,authenticated;GRANT SELECT ON public.cash_counter_events TO authenticated;GRANT ALL ON public.cash_counter_events TO service_role;
ALTER TABLE public.cash_counter_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY cash_events_read ON public.cash_counter_events FOR SELECT TO authenticated USING(public.can_access_branch(business_id,branch_id));
CREATE UNIQUE INDEX cash_open_once ON public.cash_counter_events(session_id) WHERE kind='open';CREATE UNIQUE INDEX cash_close_once ON public.cash_counter_events(session_id) WHERE kind='close';
CREATE TABLE public.commerce_payments(id uuid PRIMARY KEY,business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE RESTRICT,branch_id uuid NOT NULL,period_id uuid NOT NULL,document_id uuid NOT NULL,method text NOT NULL CHECK(method IN ('cash','bank','wallet')),amount numeric(18,2) NOT NULL CHECK(amount>0 AND amount::text NOT IN ('NaN','Infinity','-Infinity')),direction text NOT NULL CHECK(direction IN ('in','out')),session_id uuid,reference text NOT NULL,actor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,payment_date date NOT NULL,request jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(business_id,document_id) REFERENCES public.commerce_documents(business_id,id) ON DELETE RESTRICT,FOREIGN KEY(business_id,branch_id) REFERENCES public.branches(business_id,id) ON DELETE RESTRICT,FOREIGN KEY(period_id) REFERENCES public.financial_periods(id) ON DELETE RESTRICT);
REVOKE ALL ON public.commerce_payments FROM anon,authenticated;GRANT SELECT ON public.commerce_payments TO authenticated;GRANT ALL ON public.commerce_payments TO service_role;
ALTER TABLE public.commerce_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY commerce_payments_read ON public.commerce_payments FOR SELECT TO authenticated USING(public.can_access_branch(business_id,branch_id));
CREATE INDEX commerce_payments_document ON public.commerce_payments(business_id,document_id);
CREATE TRIGGER commerce_document_immutable BEFORE UPDATE OR DELETE ON public.commerce_documents FOR EACH ROW EXECUTE FUNCTION public.block_mutation();
CREATE TRIGGER commerce_stock_immutable BEFORE UPDATE OR DELETE ON public.commerce_stock_movements FOR EACH ROW EXECUTE FUNCTION public.block_mutation();
CREATE TRIGGER commerce_journal_immutable BEFORE UPDATE OR DELETE ON public.commerce_journal_entries FOR EACH ROW EXECUTE FUNCTION public.block_mutation();
CREATE TRIGGER commerce_payment_immutable BEFORE UPDATE OR DELETE ON public.commerce_payments FOR EACH ROW EXECUTE FUNCTION public.block_mutation();
CREATE TRIGGER cash_events_immutable BEFORE UPDATE OR DELETE ON public.cash_counter_events FOR EACH ROW EXECUTE FUNCTION public.block_mutation();
CREATE TRIGGER commerce_document_audit AFTER INSERT ON public.commerce_documents FOR EACH ROW EXECUTE FUNCTION public.audit_row();
CREATE TRIGGER commerce_payment_audit AFTER INSERT ON public.commerce_payments FOR EACH ROW EXECUTE FUNCTION public.audit_row();
CREATE TRIGGER cash_event_audit AFTER INSERT ON public.cash_counter_events FOR EACH ROW EXECUTE FUNCTION public.audit_row();
CREATE FUNCTION public.commerce_open_period(_business uuid,_period uuid,_date date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.financial_periods;BEGIN SELECT * INTO p FROM public.financial_periods WHERE id=_period AND business_id=_business FOR SHARE;IF NOT FOUND OR p.status<>'open' OR _date NOT BETWEEN p.start_date AND p.end_date THEN RAISE EXCEPTION 'An open financial period covering this date is required';END IF;END $$;
REVOKE ALL ON FUNCTION public.commerce_open_period(uuid,uuid,date) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.commerce_stock_balance(_business uuid,_branch uuid,_variant uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT sum(quantity) FROM public.stock_movements WHERE business_id=_business AND branch_id=_branch AND variant_id=_variant),0)+coalesce((SELECT sum(quantity) FROM public.commerce_stock_movements WHERE business_id=_business AND branch_id=_branch AND variant_id=_variant),0);$$;
REVOKE ALL ON FUNCTION public.commerce_stock_balance(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
COMMENT ON TABLE public.commerce_journal_entries IS 'Minimal balanced operational posting accounts, not full accounting or inventory valuation. Purchases uses periodic purchase accounting; no COGS or profit claim.';